code.regionString:
if ~import
    syms m0 l real positive
    syms x y z real positive
    r = [x,y,z]; % Радиус-вектор до точки
    ro = sym('ro', 'real'); %Плотность магнитного момента
    rm = [l,0,0]; %Радиус-вектор до элементарного элменета катушки
    %B = [Bx, By, Bz];
    assumptions

    vec_ro = [ro,0,0]
    dB = (m0/(4*pi)) * (3*(r-rm)*dot(vec_ro,(r-rm))/mynorm(r-rm)^5-vec_ro/mynorm(r-rm)^3)
    dipolB_vec = (m0/(4*pi)) * (3*r*dot(vec_ro*L*numel(L0), r)/mynorm(r)^5 - (vec_ro*L*numel(L0))/mynorm(r)^3)

    syms bx by bz b real

    %Интегрирование Bx
    fn= 1/((l-x)^2+(y)^2+(z)^2)^sym(3/2)
    half_Bx1(l) = int(fn,l)
    fn = (l-x)*(l-x)/(mynorm([l-x,y,z]))^5
    half_Bx2(l) = 3*int(fn,l)
    Bxx = repelem(sym('0'), numel(L0));
    for i = 1:numel(L0)
       Bxx(i) = (m0*ro/(4*pi))*((half_Bx2(L0(i)+L)-half_Bx2(L0(i)))-(half_Bx1(L0(i)+L)-half_Bx1(L0(i))));
    end
    Bx = sum(Bxx)
    fn_Bx = matlabFunction(subs(simplify(Bx),m0,4e-7*pi));
    fn_rox = matlabFunction(subs(simplify(solve(bx == Bx, ro)),m0,4e-7*pi));

    %Интегрирование By
    Byy = repelem(sym('0'), numel(L0));
    for i = 1:numel(L0)
       Byy(i) = simplify(subs(int(dB(2),l),l,L0(i)+L) - subs(int(dB(2),l),l,L0(i)));
    end
    By = sum(Byy)
    fn_By = matlabFunction(subs(simplify(By),m0,4e-7*pi));
    fn_roy = matlabFunction(subs(simplify(solve(by == By, ro)),m0,4e-7*pi));

    %Интегрирование Bz
    Bzz = repelem(sym('0'), numel(L0));
    for i = 1:numel(L0)
       Bzz(i) = simplify(subs(int(dB(3),l),l,L0(i)+L) - subs(int(dB(3),l),l,L0(i)));
    end
    Bz = sum(Bzz)
    fn_Bz = matlabFunction(subs(simplify(Bz),m0,4e-7*pi));
    %fn_roz = matlabFunction(subs(simplify(solve(bz == Bz, ro)),m0,4e-7*pi));

    %Модуль вектора B соленоида
    B = mynorm([Bx,By,Bz]);
    %Модуль вектора B магнитного момента
    dipolB = mynorm(dipolB_vec);

    %Относительная погрешность разности моделей
    delt_models = abs((dipolB-B)/B)*100
    RelativeError = sym('delta', {'real', 'positive'})
    %sl = solve(delt_models == RelativeError, r);

    fn_B = matlabFunction(subs(B,m0,4e-7*pi));
    %sl = solve(b == subs(B,m0,4e-7*pi), ro);

    %fn_ro = matlabFunction(simplify(sl(1)));
    %save D:\Bezmen\PavelSheptuhin\fn_ro

    %fn_ro = matlabFunction(sl(1));
    clear bx by bz b sl
    %dot - скалярное произведение векторов
end

if false
    disp("Рассчёт ближней границы")
    xdata = linspace(0.1,1.5,100);
    ydata = linspace(0.1,1.5,100);
    zdata = linspace(0.1,0.1,100);
    r = sqrt(sum([xdata;ydata;zdata].^2));
    beacon = MagneticMoment(0,0,0,RO*L,0,0);
    [var1, var2, var3] = beacon.Field(xdata, ydata, zdata);
    %x состовляющая
    err = 100*abs(var1 - fn_Bx(repmat(RO, size(xdata)), xdata, ydata, zdata))./ fn_Bx(repmat(RO, size(xdata)), xdata, ydata, zdata);
    figure;
    plot(r, err);
    xlabel("[м]"); ylabel("[%]");
    grid on;

    figure;
    plot(r, var1, r, fn_Bx(repmat(RO, size(xdata)), xdata, ydata, zdata));
    xlabel("[м]"); ylabel("[]");
    grid on;
    %y состовляющая
    err = 100*abs(var2 - fn_By(repmat(RO, size(xdata)), xdata, ydata, zdata))./ fn_By(repmat(RO, size(xdata)), xdata, ydata, zdata);
    figure;
    plot(r, err);
    xlabel("[м]"); ylabel("[%]");
    grid on;

    figure;
    plot(r, var2, r, fn_By(repmat(RO, size(xdata)), xdata, ydata, zdata));
    xlabel("[м]"); ylabel("[Тл]");
    grid on;
    %z состовляющая
    err = 100*abs(var3 - fn_Bz(repmat(RO, size(xdata)), xdata, ydata, zdata))./ fn_Bz(repmat(RO, size(xdata)), xdata, ydata, zdata);
    figure;
    plot(r, err);
    xlabel("[м]"); ylabel("[%]");
    grid on;

    figure;
    plot(r, var3, r, fn_Bz(repmat(RO, size(xdata)), xdata, ydata, zdata));
    xlabel("[м]"); ylabel("[]");
    grid on;

    %Модуль
    disp("Модуль")
    figure;
    plot(r, mynorm([var1; var2; var3]), r, fn_B(repmat(RO, size(xdata)), xdata, ydata, zdata))
    xlabel("[м]"); ylabel("[Тл]");
    grid on;

    figure;
    plot(r, abs((mynorm([var1; var2; var3])-fn_B(repmat(RO, size(xdata)), xdata, ydata, zdata))./fn_B(repmat(RO, size(xdata)), xdata, ydata, zdata))*100)
    xlabel("[м]"); ylabel("[%]");
    grid on;
    %clear xdata ydata zdata r
end

%{
bz = repelem(0,size(bx,2));

b = mynorm([bx;by;bz]);
num_ro = fn_ro(b,r_in(1,:),r_in(2,:),r_in(3,:));%Почему то выдаёт2 решения
delta_ro = abs(tinv(0.95, size(num_ro(1,:),2))*std(num_ro(1,:))/sqrt(size(num_ro(1,:),2)))
RO = mean(num_ro(1,:));
disp("RO = "+num2str(RO)+"+-"+num2str(delta_ro));
disp("Относительная погрешность: "+num2str(100*delta_ro/RO)+"%")

bz0_fg1 = figure("Name","Bx");
title("Bx при занулении эксп. Bz"); xlabel("x [м]"); ylabel("B_x [Тл]");
plot(r_in(1,:),bx);
grid on; grid minor;
hold on
X = -29e-2:1e-2:29e-2;
N = size(X,2);
bx_aprox = fn_Bx(repelem(RO,N),X,repelem(r_in(2,1),N),repelem(r_in(3,1),N));
plot(X,bx_aprox,"--");
bx_aprox_pos_delta = fn_Bx(repelem(RO+delta_ro,N),X,repelem(r_in(2,1),N),repelem(r_in(3,1),N));
bx_aprox_neg_delta = fn_Bx(repelem(RO-delta_ro,N),X,repelem(r_in(2,1),N),repelem(r_in(3,1),N));
plot(X,bx_aprox_pos_delta,":black");
plot(X,bx_aprox_neg_delta,":black");
%clear N X
legend("B_x","fn_{Bx}")
hold off


bz0_fg2 = figure("Name","By");
title("By при занулении эксп. Bz"); xlabel("x [м]"); ylabel("B_y [Тл]");
plot(r_in(1,:),by);
grid on; grid minor;
hold on
%X = -29e-2:1e-2:29e-2;
%N = size(X,2);
by_aprox = fn_By(repelem(RO,N),X,repelem(r_in(2,1),N),repelem(r_in(3,1),N));
plot(X,by_aprox,"--");
by_aprox_pos_delta = fn_By(repelem(RO+delta_ro,N),X,repelem(r_in(2,1),N),repelem(r_in(3,1),N));
by_aprox_neg_delta = fn_By(repelem(RO-delta_ro,N),X,repelem(r_in(2,1),N),repelem(r_in(3,1),N));
plot(X,by_aprox_pos_delta,":black");
plot(X,by_aprox_neg_delta,":black");
%clear N X
legend("B_y","fn_{By}")
hold off

bz0_fg3 = figure("Name","Bz");
title("Bz при занулении эксп. Bz"); xlabel("x [м]"); ylabel("B_z [Тл]");
plot(r_in(1,:),bz);
grid on; grid minor;
hold on
%X = -29e-2:1e-2:29e-2;
%N = size(X,2);
bz_aprox = fn_Bz(repelem(RO,N),X,repelem(r_in(2,1),N),repelem(r_in(3,1),N));
plot(X,bz_aprox,"--");
bz_aprox_pos_delta = fn_Bz(repelem(RO+delta_ro,N),X,repelem(r_in(2,1),N),repelem(r_in(3,1),N));
bz_aprox_neg_delta = fn_Bz(repelem(RO-delta_ro,N),X,repelem(r_in(2,1),N),repelem(r_in(3,1),N));
plot(X,bz_aprox_pos_delta,":black");
plot(X,bz_aprox_neg_delta,":black");
legend("B_z","fn_{Bz}")
hold off

bz0_fg5= figure("Name", "B");
title("B при занулении эксп. Bz"); xlabel("x [м]"); ylabel("B [Тл]");
plot(r_in(1,:),mynorm([bx;by;bz]));
grid on; grid minor;
hold on
%X = -29e-2:1e-2:29e-2;
%N = size(X,2);
b_aprox = fn_B(repelem(RO,N),X,repelem(r_in(2,1),N),repelem(r_in(3,1),N));
plot(X,b_aprox,"--");
b_aprox_pos_delta = fn_B(repelem(RO+delta_ro,N),X,repelem(r_in(2,1),N),repelem(r_in(3,1),N));
b_aprox_neg_delta = fn_B(repelem(RO-delta_ro,N),X,repelem(r_in(2,1),N),repelem(r_in(3,1),N));
plot(X,b_aprox_pos_delta,":black");
plot(X,b_aprox_neg_delta,":black");
legend("B","fn_{B}")
hold off

bz0_fg51 = figure("Name", "B_map3");
quiver3(X,repelem(r_in(2,1),N),repelem(r_in(3,1),N), bx_aprox, by_aprox, bz_aprox, "Color","black");
hold on
quiver3(r_in(1,:),r_in(2,:),r_in(3,:), bx, by, bz, "Color","blue");
xlabel("x [м]"); ylabel("y [м]"); zlabel("z [м]");
%Положение катушки
[Xc,Yc,Zc] = cylinder(20.9e-3/2);
Zc = Zc.*185e-3;
surf(Xc,Yc,Zc, "FaceAlpha",0.1,"FaceColor","red")

legend("fn_{B}", "B", "Катушка");
clear Xc Yc cZ
hold off

bz0_fg52 = figure("Name", "B_map2");
quiver(X,repelem(r_in(2,1),N), bx_aprox, by_aprox, "Color","black");
hold on
quiver(r_in(1,:),r_in(2,:), bx, by, "Color","blue");
xlabel("x [м]"); ylabel("y [м]"); %zlabel("z [м]");
legend("fn_{B}", "B");
rectangle("Position",[0, -20.9e-3/2, 185e-3, 20.9e-3])%Положение катушки
hold off

clear N X

%}

%{
syms x y z x0 y0 z0 r
sl = solve((x-x0)^2+(y-y0)^2 == r^2, y)

clearvars -except L fn_Bx fn_By fn_Bz fn_B r_in bx by bz mynorm
syms M x y z xx yy zz m0 b real
I = 99e-3;%Ток в катушке
n = 700;% Число витков
D = 20.9e-3;% Диаметр катушки
d_in = 13.5e-3
ro = [1,0,0]*I*pi*(D/2)^2*n/L;%Плотность магнитного момента катушки

%Зададим уравненияе описывающее геометрию сердечника
R = 1e-2;%м
x0 = 0;
y0 = 0;
z0 = d_in/2-R;
L_core = L;
geom_core = (yy-y0)^2+(zz-z0)^2 == R^2
sl = solve(geom_core,zz)

r = [x,y,z]; %Радиус вектор до точки
rm = [xx,yy,zz]; % Радиус-вектор до элемента объёма сердечника
vec_M = [M,0,0]; % Вектор намагниченности вещества
dB_core = (m0/(4*pi)) * (3*(r-rm)*dot(vec_M,(r-rm))/mynorm(r-rm)^5-vec_M/mynorm(r-rm)^3) % Элемент индукции созданный сердечником
dB_core(1)
dB_core(2)
dB_core(3)
%{
%Получение Bx_core с переходом в цилиндрическую систему координат
%Не получилось
rho = sym('rho',['real','positive'])%Радиус до точки в которой ищется поле
rho_c = sym('rho_c',['real','positive'])%Радиус до элемента объёма сердечника

phi = sym('phi',['real','positive'])%Угол до точки
phi_c = sym('phi_c',['real','positive'])% угол до элемента объёма

fn = subs(-1/mynorm(r-rm)^3,[y z yy zz], [rho*cos(phi), rho*sin(phi), rho_c*cos(phi_c), rho_c*sin(phi_c)])
%}

%Без перехода в цилиндрическую систему координат
fn = -1/mynorm(r-rm)^3
var = int(fn,zz)
var = subs(var,zz,sl(2))-subs(var,zz,sl(1))
var = int(var, yy)
var = subs(var,yy,R)-subs(var,yy,-R)
var = int(var, xx)
var = subs(var,xx,L)-subs(var,xx,0)
half_Bx1 = var
fn = ((x-xx)^2)/(mynorm(r-rm))^5
var = int(fn,zz)
var = subs(var,zz,sl(2))-subs(var,zz,sl(1))
var = int(var, yy)
var = subs(var,yy,R)-subs(var,yy,-R)
var = int(var, xx)
var = subs(var,xx,L)-subs(var,xx,0)
half_Bx2 =  var

Bx_core = (m0*M/(4*pi))*(half_Bx1 + 3*half_Bx2)
sl = solve(Bx_core == b,M)
%b_ferr_x = bx - fn_Bx(ro,r_in)
%}
